Consumer thread                         Producer thread

synchronized(lock) {   // acquire
  while (queue.isEmpty())
    lock.wait();  --- releases lock + sleeps (atomic)
                                        synchronized(lock) {  // can now enter
                                          queue.add(x);
                                          lock.notify();      // wake consumer
                                        }   // lock released
  // wakes, REACQUIRES lock
  x = queue.remove();
}

// the loop matters
synchronized (lock) {
    while (queue.isEmpty()) lock.wait();   // not 'if'
    return queue.remove();
}

// why 'if' is a bug: two consumers, one item
// C1 waits, C2 waits. Producer adds 1 item, notifyAll().
// C1 wakes, reacquires lock, removes the item.
// C2 wakes, reacquires lock, queue is EMPTY again.
//   with if:    C2 calls remove() on an empty queue -> error
//   with while: C2 re-checks isEmpty() and waits again
